import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Downloading cards","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/card-download.md","filePath":"user/running-the-event/card-download.md"}'),n={name:"user/running-the-event/card-download.md"};function s(i,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="downloading-cards" tabindex="-1">Downloading cards <a class="header-anchor" href="#downloading-cards" aria-label="Permalink to &quot;Downloading cards&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators at the finish / download station.</p><p>Downloading cards is the core during-event action: a competitor finishes, inserts their card in the reader, and Manager turns the punches into a result. This page covers connecting the reader, the download, what each result means, and the one-click fixes available right after a download.</p><blockquote><p><strong>Note:</strong> This page is about reading competitors&#39; cards at the finish. To recover punches from a <em>control unit&#39;s</em> backup memory, see <a href="./station-memory">Station Memory</a>; for radio punches arriving from the field, see <a href="./radio-punches">Radio punches</a>.</p></blockquote><h2 id="before-you-start-browser-and-connection" tabindex="-1">Before you start: browser and connection <a class="header-anchor" href="#before-you-start-browser-and-connection" aria-label="Permalink to &quot;Before you start: browser and connection&quot;">​</a></h2><p>Reading a card reader in the browser uses the <strong>Web Serial API</strong>, which has two requirements:</p><ul><li><strong>Chrome or Edge</strong> (version 89+), <strong>or Firefox</strong> (version 151+), on a desktop or laptop. Safari, older Firefox and phone/tablet browsers don&#39;t support Web Serial and won&#39;t show the reader controls.</li><li><strong>A secure connection.</strong> On the <strong>computer running the server</strong> this is free — open Manager at <code>http://localhost:5154/manager</code> and you&#39;re done. On a <strong>separate download laptop</strong> you must turn on HTTPS and trust meshO&#39;s certificate once. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a> for the full setup; the <strong>Card downloads</strong> page will tell you (<strong>Secure Connection Required</strong>) if it&#39;s needed and not yet in place.</li></ul><blockquote><p><strong>On a managed Firefox, check it&#39;s not switched off.</strong> Firefox added Web Serial in version 151, but it&#39;s disabled by default under Firefox Enterprise Policies — so a laptop supplied by a workplace or school may show no reader controls even on 151+. Either use Chrome or Edge on that machine, or have whoever manages it allow Web Serial. Firefox also asks permission the first time you pick a port, with its own confirmation step on top of the usual device chooser.</p></blockquote><blockquote><p><strong>On a separate laptop, reach the server by its IP.</strong> Download laptops usually run Chrome, and Chrome frequently can&#39;t resolve the server&#39;s computer name, so the name-based link may simply fail to load with <code>DNS_PROBE_FINISHED_NXDOMAIN</code>. Use the link tagged <strong>IP</strong> in <strong>Settings → Server → Access links</strong>. See <a href="./../reference/server-addresses">Reaching the server: name or IP</a>. (Firefox looks names up through the operating system, so the name link is more likely to work there — but the IP link works in every browser, and it&#39;s the one to reach for if anything is misbehaving.)</p></blockquote><p>You&#39;ll also need a <strong>SportIdent USB reader station</strong> — a BSM7-USB or BSM8-USB (the <em>mini Reader</em>) — plugged into the computer.</p><blockquote><p><strong>On a Mac, install the reader driver first.</strong> macOS doesn&#39;t recognise SportIdent&#39;s USB stations out of the box, so no serial port is created and the browser&#39;s device chooser comes up empty. Install the Silicon Labs CP210x driver once per Mac — see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>. Windows and Linux don&#39;t need this.</p></blockquote><blockquote><p><strong>Note — EMIT events:</strong> If your event&#39;s timing system is set to EMIT rather than SportIdent, the same <strong>Card downloads</strong> page handles it: you&#39;ll be asked which reader you connected (MTR4 or 250), and the panel shows EMIT-specific reader diagnostics. The card-reading flow below is otherwise the same.</p></blockquote><h2 id="connecting-the-reader" tabindex="-1">Connecting the reader <a class="header-anchor" href="#connecting-the-reader" aria-label="Permalink to &quot;Connecting the reader&quot;">​</a></h2><p>Open <strong>Card downloads</strong> from the navigation menu, then:</p><ol><li>You&#39;ll see <strong>Connect SportIdent Reader</strong> with a <strong>Select Device</strong> button. (If you instead see <em>Event Not Started</em> or <em>Event Completed</em>, the event isn&#39;t live — downloads are only accepted while the event is in progress.)</li><li>Plug the reader into a USB port and click <strong>Select Device</strong>. The browser shows a system dialog listing serial devices — pick the reader and confirm. (On a Mac, if the reader isn&#39;t in that list, you&#39;re missing the driver — see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>.)</li><li>The status chip turns green and reads <strong>Listening</strong>. The panel now prompts <strong>Insert SportIdent Card</strong>.</li></ol><p>You only pick the device once per session. The green <strong>Listening</strong> chip is your &quot;ready to read&quot; signal — if it&#39;s amber (<strong>Connected</strong>) the reader is attached but not yet listening. Once connected, the reader keeps working as you move around Manager — but <strong>don&#39;t refresh the browser window</strong>, or you&#39;ll have to reconnect (see <a href="#downloads-appear-anywhere">Downloads appear anywhere</a>).</p><h2 id="reading-a-card-—-the-normal-flow" tabindex="-1">Reading a card — the normal flow <a class="header-anchor" href="#reading-a-card-—-the-normal-flow" aria-label="Permalink to &quot;Reading a card — the normal flow&quot;">​</a></h2><p>With the reader listening, ask the user to insert their card:</p><ol><li>A progress bar appears, showing the card number and type while it reads.</li><li>A <strong>result banner</strong> replaces it with the outcome — for a clean run, a green <strong>OK</strong> banner with the competitor&#39;s name, class, course, race time, and current place in their class. If the runner is behind the class leader, the gap follows the time in brackets — <code>Place 3 of 34 | Time 47:23 [+1:36]</code> — when the banner is wide enough to fit it on the same line. On a narrow banner, such as the dashboard tile in a small window, the gap is left out and the line stays the same.</li></ol><p>That&#39;s the whole loop, several seconds per card.</p><h3 id="where-the-download-shows-up" tabindex="-1">Where the download shows up <a class="header-anchor" href="#where-the-download-shows-up" aria-label="Permalink to &quot;Where the download shows up&quot;">​</a></h3><p>What you see depends on which screen you&#39;re on when a card downloads:</p><ul><li><strong>On the Card downloads page</strong> — the reading progress and the result appear in the panel on the left, and every read is added to the <a href="#the-download-history-table">history table</a> on the right.</li><li><strong>On the dashboard</strong> — the <strong>Download Card</strong> tile changes state as the card reads and shows the result in place, so you can leave the dashboard up and still watch downloads land.</li><li><strong>On any other screen</strong> — the result pops up in a small panel at the <strong>bottom-right</strong> of the window once the card has finished downloading. Routine results fade after a few seconds; one that needs attention (an <strong>Unassigned</strong> card) stays until you handle or close it.</li></ul><p>It&#39;s the same result banner each way, with the same one-click fixes (below) when a download needs them.</p><h2 id="what-the-result-banner-tells-you" tabindex="-1">What the result banner tells you <a class="header-anchor" href="#what-the-result-banner-tells-you" aria-label="Permalink to &quot;What the result banner tells you&quot;">​</a></h2><p>The banner colour and label depend on what Manager made of the punches:</p><table tabindex="0"><thead><tr><th>Banner</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>Green <strong>OK</strong></td><td>A valid result — name, class, course, race time, and place are shown, plus the gap to the class leader if it fits</td><td>Nothing</td></tr><tr><td><strong>MP</strong> (Missing Punch)</td><td>One or more required controls weren&#39;t punched; the missing control codes are listed</td><td>If it&#39;s a class/course mix-up, use the <a href="#fast-fixes-right-after-a-download">fast fixes</a></td></tr><tr><td><strong>DNF</strong></td><td>Did not finish</td><td>Correct if they retired; otherwise investigate later</td></tr><tr><td>Orange <strong>Unassigned</strong></td><td>The card number isn&#39;t registered to any competitor</td><td>Assign it to a competitor, or add one — see <a href="#fast-fixes-right-after-a-download">fast fixes</a></td></tr><tr><td><strong>Duplicate</strong></td><td>This card has already been downloaded for this competitor</td><td>Normal if you re-read the same card — the existing result stands</td></tr><tr><td><strong>Not competing</strong></td><td>The card matches a competitor who has no class assigned</td><td>Assign a class and re-check</td></tr><tr><td><strong>Error</strong></td><td>Something went wrong processing the download</td><td>Re-read the card; if it persists, see <a href="./../reference/troubleshooting">Troubleshooting</a></td></tr></tbody></table><p>For the rules behind OK / MP / DNF and how race time is worked out, see <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><h2 id="fast-fixes-right-after-a-download" tabindex="-1">Fast fixes right after a download <a class="header-anchor" href="#fast-fixes-right-after-a-download" aria-label="Permalink to &quot;Fast fixes right after a download&quot;">​</a></h2><p>When a download needs attention, Manager offers one-click fixes <strong>on the panel, for the most recent card</strong> — the quickest moment to sort it out, while the runner is still at the desk. (Read the next card and the panel moves on; you can still fix any past download from the <a href="#the-download-history-table">history table</a> or its detail dialog.)</p><p><strong>Unknown card (Unassigned).</strong> When the card number matches nobody in the current event:</p><ul><li>If the number is recognised in your competitor list (for instance from an Eventor entry not yet added to the event), a one-click <strong>Assign to <em>name</em></strong> button appears — it adds that person and assigns the download in one step.</li><li>Otherwise, <strong>Assign to existing</strong> lets you search for the competitor and assign the card to them. The search includes people from the entry list who haven&#39;t been added yet.</li><li>Or <strong>Add Competitor</strong> opens the add dialog, pre-filled with the card number (and the class Manager inferred from the punches), to create someone new on the spot.</li></ul><p>This is also how you fix a <strong>wrong card</strong> — e.g. someone ran on the wrong hire card. Assign the download to the competitor who actually ran it.</p><p>At a club training or other event where nobody enters beforehand, Manager can enter unknown cards itself and show the result straight away — see <a href="./../event-setup/low-key-events">Low-key events</a>.</p><p><strong>No class (Not competing).</strong> If the card matches a competitor with no class, pick a class under <strong>Assign class and re-check</strong> and Manager re-evaluates against that class&#39;s course.</p><p><strong>Missing punch (MP).</strong> If the punches don&#39;t fit the assigned course:</p><ul><li>When the same punches <em>do</em> satisfy another class&#39;s course, Manager suggests it — <em>OK for <strong>W21A</strong> [Hard 2]</em> — with a <strong>Change class</strong> button to accept the reassignment in one click. This is the common &quot;started in the wrong class&quot; fix.</li><li>Otherwise, use <strong>Change class and re-check</strong> to choose a class yourself and re-evaluate.</li></ul><blockquote><p><strong>The MP slip waits while you do this.</strong> Most mis-punches are a wrong-course mix-up, so printing straight away means printing twice. An arc around a small printer icon on the banner counts the window down (20 seconds by default); correct the class and the <em>corrected</em> slip prints at once. Press the <strong>✕</strong> beside it, or open any dialog about that runner, to end the wait with nothing printed. Full detail — including the setting — in <a href="./splits-printing#mis-punches-wait-before-they-print">Mis-punches wait before they print</a>.</p></blockquote><h2 id="the-card-download-detail-dialog" tabindex="-1">The card download detail dialog <a class="header-anchor" href="#the-card-download-detail-dialog" aria-label="Permalink to &quot;The card download detail dialog&quot;">​</a></h2><p>Click any card number (on the panel or in the history table) to open the <strong>Card Download</strong> detail dialog. It shows the <strong>punch-by-punch breakdown</strong> — every control, code, and split — alongside the class, course, and status. From here you can, for <em>any</em> download (not just the latest):</p><ul><li><strong>Assign</strong> the card to a competitor (or add a new one), or <strong>Reassign</strong> it to a different competitor</li><li><strong>Change class / course &amp; re-check</strong> — re-evaluate against a different class or course</li><li><strong>Unassign</strong> the download from its competitor</li><li><strong>Delete</strong> the download entirely</li></ul><p>Use this dialog when the quick panel actions have already scrolled past, or when you need to see exactly which controls were punched and in what order.</p><h2 id="the-download-history-table" tabindex="-1">The download history table <a class="header-anchor" href="#the-download-history-table" aria-label="Permalink to &quot;The download history table&quot;">​</a></h2><p>The right side of the page lists every card read, newest first. It&#39;s <strong>searchable</strong> (by card number or name) and <strong>filterable by status</strong> (e.g. show only <em>Unassigned</em> or <em>MP</em>). For each row you can:</p><ul><li>Click the <strong>card number</strong> to open the detail dialog</li><li>Click the <strong>competitor name</strong> to open their <strong>Edit competitor</strong> dialog — or, for an unassigned card with a provisional (italic) name, click it to add that person and assign in one step</li><li>Change the <strong>class</strong> inline with the dropdown in the Class column</li><li><strong>Print splits</strong> with the printer icon (see below)</li></ul><p>The status column shows the competitor&#39;s current status chip, the course, or an orange <strong>Unassigned</strong> chip.</p><h2 id="downloads-appear-anywhere" tabindex="-1">Downloads appear anywhere <a class="header-anchor" href="#downloads-appear-anywhere" aria-label="Permalink to &quot;Downloads appear anywhere&quot;">​</a></h2><p>You don&#39;t have to stay on the <strong>Card downloads</strong> page — once the reader is connected, it keeps reading as you move around Manager, and each result shows up in whichever form fits the screen you&#39;re on (<a href="#where-the-download-shows-up">as above</a>).</p><blockquote><p><strong>Warning — don&#39;t refresh the browser window.</strong> Navigating between Manager&#39;s screens keeps the reader connected, but <strong>reloading the page (or closing the tab) drops the connection</strong> — you&#39;ll be back at <strong>Connect SportIdent Reader</strong> and have to click <strong>Select Device</strong> to carry on. Cards you&#39;ve already read are safe: they&#39;re stored on the server the moment they download. It&#39;s only the live reader link that has to be re-established.</p></blockquote><h2 id="printing-splits" tabindex="-1">Printing splits <a class="header-anchor" href="#printing-splits" aria-label="Permalink to &quot;Printing splits&quot;">​</a></h2><p>If you have a splits printer set up, the printer icon on each history row prints that competitor&#39;s split times. To print automatically on every download, turn on <strong>Automatic print splits on download</strong> — globally in <a href="./../reference/settings">Settings</a>, or per event under <strong>Edit</strong> event details → <strong>Splits print</strong>. See <a href="./splits-printing">Printing splits</a> for the whole picture: what a printout contains, and whether to print on one printer at the server or on a printer at each download station.</p><h2 id="hire-items" tabindex="-1">Hire items <a class="header-anchor" href="#hire-items" aria-label="Permalink to &quot;Hire items&quot;">​</a></h2><p>If a downloaded card is one of your hire cards — or belongs to a competitor holding a compass, a map board or anything else you lend — Manager prompts you to <strong>collect it all</strong> so none of it walks off. That prompt, and how to manage what you hire out, are covered in <a href="./hire-items">Hire items</a>.</p><h2 id="manual-downloads" tabindex="-1">Manual downloads <a class="header-anchor" href="#manual-downloads" aria-label="Permalink to &quot;Manual downloads&quot;">​</a></h2><p>Sometimes a runner has no card to read. A <strong>manual download</strong> lets you type their run in yourself, and Manager then evaluates it exactly as it would a card it had read — status, race time, splits, placing. Typical reasons:</p><ul><li><strong>A lost card.</strong> The runner finished but the card didn&#39;t come back. Type in their start, finish and controls (from the finish unit, the station backups or the radio punches).</li><li><strong>Two runners went round together on one card.</strong> Copy the download of the card that was read onto the runner who didn&#39;t have one.</li><li><strong>Testing.</strong> Try out a course, a class or a results screen with a made-up run before the event.</li></ul><p>Open the competitor&#39;s <strong>Edit competitor</strong> dialog and go to the <strong>Download</strong> tab. The button at the bottom of the tab is:</p><ul><li><strong>New manual download…</strong> — when the competitor has no download at all.</li><li><strong>Edit manual download…</strong> — when the download on the tab is a manual one.</li></ul><p>A competitor who already has a card read gets neither: a competitor holds one download, and a card read is the record of what their card held. Correct it on the <strong>Overrides</strong> tab instead (see <a href="./resolving-issues">Resolving issues</a>). If the read on their record isn&#39;t theirs at all, unassign or delete it from the <a href="#the-card-download-detail-dialog">card download detail dialog</a> first.</p><p>The form has a <strong>Start</strong> and a <strong>Finish</strong> time and a list of <strong>Controls</strong>, each with its code and time. Times are hours, minutes and seconds (type the digits — <code>103015</code> is 10:30:15); fractions of a second aren&#39;t used. Leave the start or finish empty if the run didn&#39;t have one, just as a card wouldn&#39;t. When you&#39;re making a new one, <strong>Copy from a download</strong> at the top fills the form from any other download in the event — this is how you copy a partner&#39;s card. Copying only reads it: that download isn&#39;t changed and stays with the competitor it belongs to. Editing doesn&#39;t offer a copy. When you&#39;re starting from nothing, <strong>Fill from course</strong> adds a row for each control of the runner&#39;s course, in order, ready for their times.</p><p>Nothing changes until you click <strong>Save</strong>. Manager then evaluates the run and the competitor&#39;s result updates. <strong>Cancel</strong> leaves everything as it was.</p><p>Things to know:</p><ul><li><strong>A card read is never changed.</strong> Only manual downloads can be edited. In the history table a manual download is marked <strong>Manual</strong> beside its card number.</li><li><strong>Editing replaces the manual download.</strong> The version you replaced is recorded in the competitor&#39;s <strong>Audit trail</strong> tab, and its file stays on disk, so it can turn up in <a href="#import-from-backup">Import from Backup</a>.</li><li><strong>Deleting it.</strong> <strong>Delete</strong> at the bottom of <strong>Edit manual download</strong> removes it, once you confirm. The result it gave goes too — the competitor falls back to what their radio punches say, or to no result — and <strong>New manual download…</strong> is offered again. Like any deleted download it&#39;s recorded in the <strong>Audit trail</strong> and its file stays on disk.</li><li><strong>A manual download belongs to the competitor you made it for.</strong> It&#39;s never matched to anyone by card number, and it never changes the competitor&#39;s card number. Correcting their card number afterwards keeps it.</li><li><strong>Times are whole seconds.</strong> Copying a download that recorded fractions of a second (SIAC beacon punches) drops the fractions, and the form tells you. The check punch isn&#39;t copied.</li><li><strong>Nothing is printed automatically</strong>, because the runner isn&#39;t standing at a download desk. Print from the <strong>Splits print</strong> tab if you need to.</li><li><strong>Not at the entry desk.</strong> The registration desk shows a competitor&#39;s download but doesn&#39;t offer manual downloads.</li></ul><h2 id="import-from-backup" tabindex="-1">Import from Backup <a class="header-anchor" href="#import-from-backup" aria-label="Permalink to &quot;Import from Backup&quot;">​</a></h2><p>Downloads are stored in the event database by the server as they&#39;re read. If downloads were taken on another machine, or you&#39;re rebuilding an event, <strong>Import from Backup</strong> (top right of the history table) scans the disk for card-download files Manager hasn&#39;t loaded yet (or were deleted) and lets you pick which to bring in. If everything on disk is already loaded, it tells you so.</p><h2 id="when-a-card-won-t-read" tabindex="-1">When a card won&#39;t read <a class="header-anchor" href="#when-a-card-won-t-read" aria-label="Permalink to &quot;When a card won&#39;t read&quot;">​</a></h2><p>If a card fails to read, the panel shows a read error rather than a result.</p><ul><li>Ask the user to remove the card and try again.</li><li>Check the reader is still <strong>Listening</strong> (green chip) — reconnect with <strong>Select Device</strong> if the chip has dropped.</li><li>Try a different USB port or cable if reads keep failing.</li></ul><p>A card that won&#39;t read in one reader will usually read in another; if a specific card fails everywhere, it may be faulty.</p><h2 id="for-problems-noticed-later" tabindex="-1">For problems noticed later <a class="header-anchor" href="#for-problems-noticed-later" aria-label="Permalink to &quot;For problems noticed later&quot;">​</a></h2><p>The fast fixes above are for the moment of download. For anything you spot after the runner has gone — a result that needs an overridden status, punches to edit, a competitor to re-evaluate — work from the competitor&#39;s record instead. See <a href="./resolving-issues">Resolving issues on the day</a>.</p><h2 id="downloading-a-card-after-you-ve-finished-the-event" tabindex="-1">Downloading a card after you&#39;ve finished the event <a class="header-anchor" href="#downloading-a-card-after-you-ve-finished-the-event" aria-label="Permalink to &quot;Downloading a card after you&#39;ve finished the event&quot;">​</a></h2><p>Downloading is only available while the event is live, but that isn&#39;t a one-way door. If someone walks out of the forest after you&#39;ve clicked <strong>Finish event</strong> — or turns up the next day with an unread card — open the event and click <strong>Restart event</strong> in the app bar. The event goes live again, you download the card as normal, and you finish the event a second time afterwards.</p><p>The late download gives the same result it would have on the day: the card carries the times of day the competitor punched, not elapsed time, so it doesn&#39;t matter when you read it. See <a href="./dashboard#restarting-an-event-youve-already-finished">Restarting an event you&#39;ve already finished</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — the competitor records cards are matched to</li><li><a href="./../event-setup/classes-and-courses">Classes and courses</a> — the classes and courses a download is evaluated against</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — how OK / MP / DNF and race time are decided</li><li><a href="./splits-printing">Printing splits</a> — the slip a download prints, and where the printers go</li><li><a href="./hire-items">Hire items</a> — the collect-on-download prompt and managing what you lend</li><li><a href="./../event-setup/low-key-events">Low-key events</a> — entering unknown cards, and making courses from them, automatically</li><li><a href="./station-memory">Station Memory</a> — recovering punches from a control unit&#39;s backup memory</li><li><a href="./../reference/https-and-certificates">HTTPS and certificates</a> — required to download cards in the browser on a computer other than the server</li><li><a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a> — the driver a Mac needs before the reader appears in the browser at all</li><li><a href="./../reference/sportident-cards">SportIdent cards</a> — card types and what they store</li><li><a href="./resolving-issues">Resolving issues on the day</a> — fixes for problems noticed after the download</li></ul>',76)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
